--
-- PostgreSQL database dump（11 AI RAG 高级知识库平台 · PGVector 向量数据）
--
-- 用法：在目标机器先建库并连到该库，再整体执行本脚本：
--   1) CREATE DATABASE ai_rag_vector;
--   2) 连接到 ai_rag_vector 数据库
--   3) 执行本脚本（已含 CREATE EXTENSION + 建表 + 110 条向量数据 + ivfflat 索引）
--
-- 说明：
--   业务数据全部在 MySQL 的 ai_rag 库里，这里只存向量和检索必需的过滤字段。
--   两个库通过 chunk_id 关联：chunk_id 就是 MySQL 里 knowledge_chunk.id。
--   向量维度 1024 必须与 ai_model_config 中启用的向量模型输出维度一致，
--   百炼 text-embedding-v4 默认输出 1024 维。换向量模型必须重建本表并全量重新向量化。
--

-- Dumped from database version 18.4
-- Dumped by pg_dump version 18.4

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET transaction_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

--
-- Name: vector; Type: EXTENSION; Schema: -; Owner: -
--

--
-- 向量类型依赖 pgvector 扩展，必须先创建，否则下面的 vector(1024) 会报错
--
CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;

--
-- 支持重复执行：先删旧表和序列（CASCADE 连同索引一起清掉），再重建
--
DROP TABLE IF EXISTS public.knowledge_chunk_vector CASCADE;
DROP SEQUENCE IF EXISTS public.knowledge_chunk_vector_id_seq CASCADE;


--
-- Name: EXTENSION vector; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON EXTENSION vector IS 'vector data type and ivfflat and hnsw access methods';


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: knowledge_chunk_vector; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.knowledge_chunk_vector (
    id bigint NOT NULL,
    chunk_id integer NOT NULL,
    kb_id integer NOT NULL,
    document_id integer,
    parent_chunk_id integer,
    chunk_type character varying(20),
    title_path character varying(500),
    content text,
    embedding public.vector(1024),
    create_time timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);


--
-- Name: knowledge_chunk_vector_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.knowledge_chunk_vector_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: knowledge_chunk_vector_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.knowledge_chunk_vector_id_seq OWNED BY public.knowledge_chunk_vector.id;


--
-- Name: knowledge_chunk_vector id; Type: DEFAULT; Schema: public; Owner: -
--

ALTER TABLE ONLY public.knowledge_chunk_vector ALTER COLUMN id SET DEFAULT nextval('public.knowledge_chunk_vector_id_seq'::regclass);


--
-- Data for Name: knowledge_chunk_vector; Type: TABLE DATA; Schema: public; Owner: -
--



--
-- Name: knowledge_chunk_vector_id_seq; Type: SEQUENCE SET; Schema: public; Owner: -
--

SELECT pg_catalog.setval('public.knowledge_chunk_vector_id_seq', 185, true);


--
-- Name: knowledge_chunk_vector knowledge_chunk_vector_pkey; Type: CONSTRAINT; Schema: public; Owner: -
--

ALTER TABLE ONLY public.knowledge_chunk_vector
    ADD CONSTRAINT knowledge_chunk_vector_pkey PRIMARY KEY (id);


--
-- Name: idx_knowledge_chunk_vector_doc; Type: INDEX; Schema: public; Owner: -
--

CREATE INDEX idx_knowledge_chunk_vector_doc ON public.knowledge_chunk_vector USING btree (document_id);


--
-- Name: idx_knowledge_chunk_vector_embedding; Type: INDEX; Schema: public; Owner: -
--

CREATE INDEX idx_knowledge_chunk_vector_embedding ON public.knowledge_chunk_vector USING ivfflat (embedding public.vector_cosine_ops) WITH (lists='100');


--
-- Name: idx_knowledge_chunk_vector_kb; Type: INDEX; Schema: public; Owner: -
--

CREATE INDEX idx_knowledge_chunk_vector_kb ON public.knowledge_chunk_vector USING btree (kb_id, chunk_type);


--
-- Name: uk_knowledge_chunk_vector_chunk; Type: INDEX; Schema: public; Owner: -
--

CREATE UNIQUE INDEX uk_knowledge_chunk_vector_chunk ON public.knowledge_chunk_vector USING btree (chunk_id);


